solution.solution.py:
from concurrent.futures import ThreadPoolExecutor


def fetch_all(urls, fetch, workers=4):
    results = {}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {url: pool.submit(fetch, url) for url in urls}
        for url, future in futures.items():
            try:
                results[url] = future.result()
            except Exception as e:
                results[url] = f"error: {e}"
    return results

unitTests:
import threading
import time

@test("results and errors")
def _():
    def fake_fetch(url):
        if "bad" in url:
            raise ConnectionError("refused")
        return len(url)
    check_eq(fetch_all(["a.com", "bad.org", "xyz.net"], fake_fetch),
             {"a.com": 5, "bad.org": "error: refused", "xyz.net": 7})
    check_eq(fetch_all([], fake_fetch), {})

@test("runs on several threads at once")
def _():
    names = set()
    def slow(url):
        names.add(threading.current_thread().name)
        time.sleep(0.05)
        return url.upper()
    start = time.perf_counter()
    out = fetch_all([f"u{i}" for i in range(8)], slow, workers=4)
    took = time.perf_counter() - start
    check_eq(out["u3"], "U3")
    check(len(names) > 1, "only one thread did the work")
    check(took < 0.35, f"took {took:.2f} s: the calls did not overlap")

